          "guides",
          "feedback",
          "privacy",
          "discord"
        ],
        isHideTitle: true,
        section: "other"
      }
    ]
  },
  [Product.POINTRON]: {
    ...resolveBaseSharedProductConfig(Product.POINTRON),
    appMenu: [...pointronNav.appMenu],
    appMenuPt: [...pointronNav.appMenuPt],
    homePath: pointronNav.homePath,
    homePathPt: pointronNav.homePathPt,
