+/** Creates namespace-scoped IndexedDB storage. */
+export function createDatafnStorage(input: {
+product: Product;
+namespace: string;
+env?: string;
+}) {
+const storage = IndexedDbStorageAdapter.createForNamespace(
+resolveDatafnBaseDbName(input),
+input.namespace,
