+for (const post of posts) {
+pendingRelations.push({ from: post.id, to: mainPost.id, content });
+}
+}
+if (posts.length > 0 && subs.length > 0) {
+const subRelation = await this.saveLinkTag("sub", "social");
+const content = {
+tags: subRelation?.id ? [subRelation.id] : []
