+const items = [...n.items];
+const fromIndex = items.findIndex((item) =>
+isSameResource(item.id, fromId)
+);
+const toIndex = items.findIndex((item) => isSameResource(item.id, toId));
+const [movedItem] = items.splice(fromIndex, 1);
+items.splice(toIndex, 0, movedItem);
+this.modify({ items });
