+imageData[i], // R
+imageData[i + 1], // G
+imageData[i + 2] // B
+]);
+}
+let centroids = pixels.slice(0, numClusters);
+let oldCentroids: number[][] = [];
+let iterations = 0;
+const maxIterations = 20;
+while (iterations < maxIterations) {
+const clusters: number[][][] = Array(numClusters)
+.fill(0)
