+case Placement.BottomCenter:
+popRef.style.top = `${triggerRect.height + offsetInPx}px`;
+break;
+case Placement.Left:
+popRef.style.right = `${triggerRect.width + offsetInPx}px`;
+break;
+case Placement.Right:
+popRef.style.left = `${triggerRect.width + offsetInPx}px`;
+break;
