+expect(clampAndConvertSample(2)).toBe(0x7fff);
+expect(clampAndConvertSample(-2)).toBeCloseTo(-0x8000, 0);
+expect(clampAndConvertSample(0.5)).toBeCloseTo(0.5 * 0x7fff);
+});
