+const samples = new Float32Array([0, 0.5, -0.5]);
+const wav = convertFloat32ArrayToWav(samples, 8000);
+const view = new DataView(wav);
+expect(view.getUint32(0, false)).toBe(0x52494646); // "RIFF"
