+expect(view.getInt16(44, true)).toBe(0);
+expect(view.getInt16(46, true)).toBe(Math.trunc(0.5 * 0x7fff));
+expect(view.getInt16(48, true)).toBe(Math.trunc(-0.5 * 0x8000));
