+const dd = date.day.toString().padStart(2, "0");
+const mm = (date.month + 1).toString().padStart(2, "0");
+const yy = String(date.year); //.slice(-2);
+if (format === "yyyy:mm:dd") {
+return `${yy}-${mm}-${dd}`;
+} else if (format === "verbose") {
+return `${dd} ${months[date.month]} ${yy}`;
+}
+return `${yy}-${mm}-${dd}`;
