+begin.setDate(1);
+end.setDate(31);
+} else if (
+period.value.type === TimePeriodType.CALENDAR_BOUND &&
+period.value instanceof Array
+) {
+const year = period.value[0];
+begin.setFullYear(year);
+begin.setMonth(0);
+begin.setDate(1);
