+} else if (
+((period.scale === TimeScale.MONTHS &&
+period.value.type === TimePeriodType.RELATIVE) ||
+(period.scale === TimeScale.DAYS &&
+period.value.type === TimePeriodType.UPPER_RELATIVE)) &&
