+MAX_SYNC_DURATION,
+"ms - may be hung"
+);
+}
+}, MAX_SYNC_DURATION);
+try {
+await pullForegroundDatafn();
+await refreshNucleumDatafnStatus();
+} catch (error) {
+console.error("Sync failed:", error);
+} finally {
+syncCompleted = true;
+if (currentSyncTimeout) {
+clearTimeout(currentSyncTimeout);
+currentSyncTimeout = null;
+}
+if (!isDestroyed) {
+isSyncing = false;
+}
+}
+}
