import { fileEmbedChannel } from "./fileEmbedChannel.store";

/** Delivers native download acknowledgements and file payloads to their pending requests. */
export function handleNativeFileMessage(message: Record<string, any>): boolean {
  if (
    (message.type === "DOWNLOAD_SUCCESS" ||
      message.type === "DOWNLOAD_ERROR") &&
    message.id
  ) {
    fileEmbedChannel.setDownloadResult(
      message.id,
      message.type === "DOWNLOAD_SUCCESS"
    );
    return true;
  }
  if (!message.type && message.id && message.data) {
    fileEmbedChannel.setFile(message.id, message.data);
    return true;
  }
  return false;
}
import { parse } from "@21n/shared-utils/json.utils";

/** Decodes only native messages from the current webview window and origin. */
export function parseNativeMessage(
  event: MessageEvent
): Record<string, any> | undefined {
  if (event?.data?.type !== "SWIFT_MESSAGE" || event.source !== window) return;
  if (event.origin !== window.location.origin && event.origin !== "null")
    return;
  const payload = event.data.payload;
  if (typeof payload !== "string" || !payload.trim().startsWith("{")) return;
  return parse(payload);
}
import { get } from "svelte/store";

import account from "@nucleum/client/runtime/account/account.store";
import { appStore } from "@nucleum/shared-state/app-context/app.store";

import context from "@nucleum/client/runtime/context.store";
import { toasts } from "@nucleum/shared-state/notifications/notification.store";

import { isExtensionEnvironment } from "@21n/shared-utils/browser-environment";

import { UserDataMode } from "@nucleum/client/runtime/account/account.type";
import { logger } from "@nucleum/client/runtime/logging/logger";

import { fileStore } from "@nucleum/shared-state/files/file.store";

import { stringify } from "@21n/shared-utils/json.utils";
import { parseAndFormatDate } from "@21n/shared-utils/datetime/date-formatting";

import {
  cloneUpAllDatafnData,
  nucleumDatafnStatus,
  type NucleumDatafnRuntime
