import {
  GlobalEvent,
  type Event
} from "@nucleum/shared-state/events/event.enum";
import type { IEvent } from "@21n/ui/elements/input/event.type";
import { ObservableStore } from "@nucleum/datafn/observable-store";
import { dispatchCustomEvent } from "@21n/shared-utils/dom-events";

/** Application events shared across layout, controls, and capabilities. */
class AppEventStore extends ObservableStore<IEvent> {
  constructor() {
    super("appEvents");
    this.reset();
  }
  reset() {
    this.set({ event: GlobalEvent.NONE, value: false });
  }
  publish(m: Event, value: any = undefined) {
    this.update((n: IEvent) => {
      return { event: m, value };
    });
    this.reset();
    if (typeof window !== "undefined") {
      dispatchCustomEvent(GlobalEvent.EVENT, {
        event: m,
        value
      });
    }
  }

  nav(path: string) {
    this.publish(GlobalEvent.NAV, { path });
  }
}

export const appEvents = new AppEventStore();
<svelte:options runes={true} />

<script lang="ts">
  import { isTextElement } from "@21n/ui/actions/interaction-dom";
  import type { IKeyboardShortcut } from "@21n/ui/elements/keyboard/shortcut.type";
  let {
    isAllowFromTextInput = false,
    checkShortcut,
    shortcuts
  }: {
    isAllowFromTextInput?: boolean;
    checkShortcut: (
      event: KeyboardEvent,
      shortcut: string | IKeyboardShortcut
    ) => boolean;
    shortcuts: {
      shortcut: string | IKeyboardShortcut;
      callback: () => void;
    }[];
  } = $props();

  function shortcutListener(event: KeyboardEvent) {
    const isTextInputSource = isTextElement(event.target);
    if (isTextInputSource && !isAllowFromTextInput) return;
    const result = shortcuts.find((s) => checkShortcut(event, s.shortcut));
    if (result) {
      result.callback();
      event.preventDefault();
      event.stopPropagation();
    }
  }
</script>

<svelte:document onkeydown={shortcutListener} />
