      userAgent: navigator.userAgent,
      origin,
      dapId,
      deviceFingerprint,
      host:
        import.meta.env?.VITE_HOST ??
        (typeof process !== "undefined"
          ? process.env?.PLASMO_PUBLIC_APP_URL
          : undefined) ??
