      inSeconds: timeRemainingToTakeBreak,
      message:
        "Its been " +
        breakReminderSetting / 60 +
        " minute(s) since you took a break. Please consider taking a break.",
      timestamp: new Date().getTime() + timeRemainingToTakeBreak * 1000,
      title: "Break Reminder",
      sound: "ping.wav",
      id: "breakReminder"
    });
